<script lang="ts">
	import { getTheme, setTheme, type Theme } from '$lib/theme.svelte';
	import { t } from '$lib/i18n';
	import { glyph } from '$lib/icons';
	// @ts-expect-error — generated by Wails
	import { SetWallpaper } from '@wails/go/gui/App.js';

	// Reflect the active scheme on the control. The visible icon names the current
	// theme; the aria-label / title name the action the next click performs.
	let isDark = $derived(getTheme() === 'dark');

	const label = $derived(isDark ? t('app.themeToLight') : t('app.themeToDark'));

	// Toggle the in-wizard theme, then switch the live Hyprland wallpaper to the
	// matching variant. The call is best-effort: the GUI runs as the session user,
	// but wallpaper switching must never break the toggle if hyprctl is unavailable
	// (e.g. dry-run on a host without Hyprland), so its rejection is swallowed.
	const onToggle = () => {
		const next: Theme = isDark ? 'light' : 'dark';
		setTheme(next);
		SetWallpaper(next).catch(() => {});
	};
</script>

<button
	type="button"
	class="theme-toggle"
	aria-pressed={isDark}
	aria-label={label}
	title={label}
	onclick={onToggle}
>
	{#if isDark}
		<!-- Moon — current theme is dark; clicking switches to light mode -->
		<span class="theme-icon nf-icon" aria-hidden="true">{glyph('f0594')}</span>
	{:else}
		<!-- Sun — current theme is light; clicking switches to dark mode -->
		<span class="theme-icon nf-icon" aria-hidden="true">{glyph('f522')}</span>
	{/if}
</button>

<style>
	.theme-toggle {
		display: inline-flex;
		align-items: center;
		justify-content: center;
		width: 36px;
		height: 36px;
		padding: 0;
		border-radius: var(--radius-pill);
		border: 1px solid var(--color-border-subtle);
		background: var(--color-bg-hover);
		color: var(--color-text-muted);
		cursor: pointer;
		transition:
			transform 0.3s var(--theme-ease),
			background 0.3s,
			color 0.3s,
			border-color 0.3s;
	}

	.theme-toggle:hover {
		transform: translateY(-2px);
		background: var(--color-surface);
		color: var(--color-text);
	}

	.theme-toggle:focus-visible {
		outline: 2px solid var(--color-focus);
		outline-offset: 2px;
	}

	.theme-icon {
		font-family: "NerdFontsSymbols Nerd Font";
